DECLARE
  d jsonb := $p${"chapter":1,"lesson_id":"37793f0c-2390-5bd1-bca2-c6f32b5f2b64","slug":"scratch-v3-klonlash","title":"Scratch 3.0: klonlar va ularni boshqarish","body":"# Scratch — klonlar va ularni boshqarish\n\n**Maqsad.** Bitta spraytdan mustaqil ko‘rinuvchi ko‘plab nusxalar hosil qilishni, klonlarning hodisa skripti va yakunlanishini tushuntirish.\n\n**Manba:** ICT 6-sinf (2021), PDF 14, 22–23. **Maqomi:** darslik kengaytmasi; 2026 spetsifikatsiyada mustaqil kvota yo‘q.\n\n## Asosiy tushunchalar\n\n- `create clone of [myself]` — spraytning **yangi klonini** yaratadi; yangi sahna yoki fayl ochmaydi.\n- `when I start as a clone` — klon yaratilganda aynan shu klon bajaradigan hodisa skripti.\n- `hide` spraytni **yashiradi**, ammo o‘chirmaydi; `show` yana ko‘rsatadi.\n- `delete this clone` — ayni klonni **yo‘q qiladi**; asl sprayt saqlanadi.\n\n## “Sharchalar” loyiha namunasi\n\nQuyidagi yozuv Scratch rangli bloklarining **matnli bayoni**, tayyor dasturlash sintaksisi emas:\n\n```text\nwhen green flag clicked\nhide\nrepeat (4)\n  create clone of [myself]\nend\n\nwhen I start as a clone\n  go to x:(pick random -100 to 100) y:(150)\n  show\n  repeat until <(y position) < (-170)>\n    change y by (-5)\n  end\n  delete this clone\n```\n\n**Tahlil:** yashirilgan asl shar o‘rniga to‘rtta klon hosil bo‘ladi. Har bir klon o‘z koordinatasini tanlaydi, pastga siljiydi va chegara ortidan yo‘q qilinadi. Klonlar soni cheklovga yetmagan deb olinadi.\n\n## Diqqat\n\nKlon yaratish va `show` bir amal emas. Klonning boshlang‘ich xususiyatlari nusxa olinayotgan sprayt holatiga asoslanadi, ammo keyingi harakati mustaqil bo‘lishi mumkin.\n\n**Mavzu testi:** 10 ta savol — `SL3-01-001` dan `SL3-01-010` gacha.","construct_id":"825fadf8-064b-53a0-b656-5b37b8f93e4e","construct_code":"S4.EXT.CLONE","group_code":"S4.EXT","construct_title":"Scratch 3.0: klonlar va ularni boshqarish","kind":"extension","items":[{"id":"SL3-01-001","ch":1,"level":"A","stem":"Klonlashda `create clone of myself` bajarilganda nima yaratiladi?","opts":["Kompyuter fayli","Yangi loyiha","Shu spraytning yangi kloni","Yangi sahna"],"correct":2,"answer":"Shu spraytning yangi kloni","why":"Asl spraytning nusxasi yaratiladi.","source":"ICT6-2021 PDF 14, 22–23","scope":"TEXTBOOK_EXTENSION","format":"Y1","uuid":"eb23ec99-8956-51c5-9231-252d62e9b64c","difficulty":1,"cognitive":"bilish","option_ids":["eedbb881-1faa-5a87-a250-4e9f8a6ae560","6ed68eef-170e-5503-b4c0-c8c670459f64","326de0fd-4747-55ce-82cd-00460d33d970","dc15be99-7261-5341-9d76-def172320a69"]},{"id":"SL3-01-002","ch":1,"level":"B","stem":"Klon yangi yaratilganda faqat klon uchun qaysi hodisa skripti ishga tushadi?","opts":["when backdrop switches to","when I start as a clone","when this sprite clicked","when green flag clicked"],"correct":1,"answer":"when I start as a clone","why":"Klon ishga tushish hodisasi alohida blokdir.","source":"ICT6-2021 PDF 14, 22–23","scope":"TEXTBOOK_EXTENSION","format":"Y1","uuid":"38f1e86c-2976-52ee-af35-d2782b5a4aa4","difficulty":2,"cognitive":"bilish","option_ids":["cd700fc4-7e97-584b-aa46-61bf73274b47","ea938189-8eb8-5f83-8798-28620bace4a1","bd657f7a-7426-53f2-8ab1-09578a789eb4","67a77244-735d-5788-b3be-0d64be16e787"]},{"id":"SL3-01-003","ch":1,"level":"C","stem":"Klonni o‘chirish, asl spraytni esa saqlab qolish uchun qaysi blok qo‘llanadi?","opts":["erase all","stop all","delete this clone","hide"],"correct":2,"answer":"delete this clone","why":"delete this clone joriy klonni o‘chiradi.","source":"ICT6-2021 PDF 14, 22–23","scope":"TEXTBOOK_EXTENSION","format":"Y1","uuid":"ad8a4ed3-f7c6-5c38-b837-e6156711bfc9","difficulty":3,"cognitive":"qollash","option_ids":["1d7a2927-68f6-5114-9a91-ecfe7c981045","f066a6b1-01f5-57d5-bdff-2fddda5bc753","8c6fac97-3fe6-5a39-bffb-416fb4fd7a97","2d51b275-f900-51f3-9b83-73a2fc0f5b92"]},{"id":"SL3-01-004","ch":1,"level":"D","stem":"Sharchalar o‘yinida asl shar yashiringan, klonlar paydo bo‘lmoqda. Buning asosiy maqsadi nima?","opts":["Sahnani ikkiga bo‘lish","Koordinatalarni o‘chirish","Bir spraytdan ko‘p mustaqil nusxa hosil qilish","Bir nechta loyiha faylini ochish"],"correct":2,"answer":"Bir spraytdan ko‘p mustaqil nusxa hosil qilish","why":"Bir originaldan ko‘p klon yaratiladi.","source":"ICT6-2021 PDF 14","scope":"TEXTBOOK_EXTENSION","format":"Y1","uuid":"b23d3c89-0009-5cf2-a44b-a1a0f9dcc377","difficulty":4,"cognitive":"qollash","option_ids":["b0027890-9f4e-5c68-8bec-906d6e2196f0","f6a17dd4-7e69-5ec0-bd77-46e65ee9db0b","06b3a6bd-51e7-58b7-a179-375bf78116ef","bd3fbc71-fa84-58fd-ba57-3eb7acfdbd63"]},{"id":"SL3-01-005","ch":1,"level":"E","stem":"`when I start as a clone` ichida `show` berilishi nimani ta’minlaydi?","opts":["Yangi sahna yuklanadi","Asl sprayt o‘chadi","Barcha klonlar to‘xtaydi","Klon ekranda ko‘rinadi"],"correct":3,"answer":"Klon ekranda ko‘rinadi","why":"Klon yaratilganda ko‘rsatiladi.","source":"ICT6-2021 PDF 14, 22–23","scope":"TEXTBOOK_EXTENSION","format":"Y1","uuid":"08e98077-3967-557d-b80b-03f8d46aae1e","difficulty":5,"cognitive":"mulohaza","option_ids":["fa4b76d0-069b-502f-aa09-0fb25f3e0b1a","13a931e9-82bb-554e-b662-1f957ca8bdb6","6c11d59c-f0a8-55ad-9271-cd4296ed6c41","ef6988d1-09a0-5669-ba57-286f0243ce75"]},{"id":"SL3-01-006","ch":1,"level":"A","stem":"Klon yaratilishida uning boshlang‘ich koordinatasi, odatda, qayerdan olinadi?","opts":["Nusxa olinayotgan spraytning joriy holatidan","Faqat oxirgi fon nomidan","Faqat sichqoncha joyidan","Sahnaning doimiy (0,0) nuqtasidan"],"correct":0,"answer":"Nusxa olinayotgan spraytning joriy holatidan","why":"Klon yaratilayotgan vaqtdagi obyekt holatini oladi; skript keyin o‘zgartirishi mumkin.","source":"ICT6-2021 PDF 14; qo‘shimcha Scratch modeli","scope":"TEXTBOOK_EXTENSION","format":"Y1","uuid":"47d32af3-417b-59e8-8ab3-4437d7cbc052","difficulty":1,"cognitive":"bilish","option_ids":["5c970ccc-f1d7-5e7a-aff8-762a2d914dd3","7ee3c55c-1959-57aa-999d-2d9448d34d3d","9715f8f6-b7f4-52a7-892c-3c174967fb7f","2ae184a6-779b-58a0-8508-033c5929e712"]},{"id":"SL3-01-007","ch":1,"level":"B","stem":"`repeat 4 [create clone of myself]` bajarilganda nechta yangi klon yaratiladi (cheklovga yetmagan)?","opts":["5","0","1","4"],"correct":3,"answer":"4","why":"Blok har takrorlanishda bittadan klon yaratadi.","source":"ICT6-2021 PDF 14; sintez","scope":"TEXTBOOK_EXTENSION","format":"Y1","uuid":"56857ffe-eb70-5485-8869-a95f1d23d0f4","difficulty":2,"cognitive":"bilish","option_ids":["2e152f93-b292-5422-964a-5d7d1f2b5f01","88f8f623-f0ac-5190-92dd-1bbce2702b92","dab51771-64a2-5266-bfd2-91397ecd3f46","0ff52c3d-9aa7-5804-b8fa-226505e3149e"]},{"id":"SL3-01-008","ch":1,"level":"C","stem":"Klonlarning bir-biridan farqli joyda chiqishi uchun qanday yondashuv mos?","opts":["Faqat asl spraytni yashirish","Klon boshlanganda x/y ni tasodifiy qiymatga o‘rnatish","Butun skriptni o‘chirish","Sahnani saqlamaslik"],"correct":1,"answer":"Klon boshlanganda x/y ni tasodifiy qiymatga o‘rnatish","why":"Har klonning koordinatasini uning start skriptida belgilash mumkin.","source":"ICT6-2021 PDF 14, 21","scope":"TEXTBOOK_EXTENSION","format":"Y1","uuid":"c9bde767-38f8-5870-985d-9a7bd3670055","difficulty":3,"cognitive":"qollash","option_ids":["e75a97ec-4f54-57be-bd29-23614046bcfd","fd9abe4b-8bcb-50fb-81bf-284d834e45fe","36ba5bce-4005-5105-9dbd-af3276d21863","f7f4af92-245a-5900-8ba7-282cdfd0953e"]},{"id":"SL3-01-009","ch":1,"level":"D","stem":"Klonning xatti-harakati mustaqil boshqarilishi uchun qaysi kod joyi maqbul?","opts":["Faqat ovoz balandligi","Faqat o‘zgaruvchi nomi","when I start as a clone ostidagi buyruqlar","Faqat fon sozlamalari"],"correct":2,"answer":"when I start as a clone ostidagi buyruqlar","why":"Klon start hodisasiga biriktirilgan buyruqlar klonda bajariladi.","source":"ICT6-2021 PDF 14, 22–23","scope":"TEXTBOOK_EXTENSION","format":"Y1","uuid":"91fe9cfd-de0b-5453-ab0e-9a1cf1e0cc5e","difficulty":4,"cognitive":"qollash","option_ids":["2151af1c-4540-5c2b-af2e-d19308573361","eb6fc915-2662-5c8e-8ba3-bd21ca8ee020","d6679502-5993-575d-82c7-88820ae44097","25263dec-100a-5cdd-8471-ae9ed6ff7881"]},{"id":"SL3-01-010","ch":1,"level":"E","stem":"`hide` bilan `delete this clone` orasidagi farq nima?","opts":["Ikkinchisi faqat tovushni o‘chiradi","Ikkalasi bir xil bo‘lib klonni yo‘q qiladi","Birinchisi barcha spraytlarni o‘chiradi","Birinchisi ko‘rinishni o‘chiradi, ikkinchisi klonni yo‘q qiladi"],"correct":3,"answer":"Birinchisi ko‘rinishni o‘chiradi, ikkinchisi klonni yo‘q qiladi","why":"Ko‘rinmas klon mavjud bo‘lishi mumkin; delete clone klon hayotini yakunlaydi.","source":"ICT6-2021 PDF 14; qo‘shimcha Scratch modeli","scope":"TEXTBOOK_EXTENSION","format":"Y1","uuid":"db82023a-91fb-506e-be23-b0e8e3312d7c","difficulty":5,"cognitive":"mulohaza","option_ids":["185e80b3-9e29-50ed-a828-5ba227c8eafb","cc7a1189-6654-5fb3-808a-d4cd328905e9","de533935-ad85-56e6-a37a-d3d198405a4d","fbed95d2-28de-5260-85fa-59e6a9715bd4"]}]}$p$::jsonb;
  mid uuid; sid uuid := (d->>'lesson_id')::uuid; cid uuid := (d->>'construct_id')::uuid;
  subj uuid; q jsonb; qid uuid; opt_id uuid; i integer;
BEGIN
  SELECT id, subject_id INTO mid, subj FROM public.modules WHERE code='M07';
  IF mid IS NULL OR subj IS NULL THEN RAISE EXCEPTION 'M07 module not found'; END IF;
  IF d->>'kind'='extension' THEN
    INSERT INTO public.constructs(id,subject_id,group_code,code,slug,title_uz,description_uz)
    VALUES(cid,subj,d->>'group_code',d->>'construct_code',lower(replace(d->>'construct_code','.','-')),
      d->>'construct_title','2026 attestatsiya uchun qo‘shimcha darslik ko‘nikmasi, spetsifikatsiyada alohida kvota emas')
    ON CONFLICT(code) DO NOTHING;
  END IF;
  SELECT id INTO cid FROM public.constructs WHERE code=d->>'construct_code' AND subject_id=subj AND group_code=d->>'group_code';
  IF cid IS NULL THEN RAISE EXCEPTION 'Missing or incompatible construct: %', d->>'construct_code'; END IF;
  IF EXISTS(SELECT 1 FROM public.lessons WHERE id=sid AND (module_id<>mid OR slug<>d->>'slug')) THEN
    RAISE EXCEPTION 'Lesson id collision, chapter %', d->>'chapter';
  END IF;
  INSERT INTO public.lessons(id,module_id,order_idx,slug,title_uz,body_mdx,est_minutes,status,blocks,blocks_kind,topic_test_question_count)
  VALUES(sid,mid,(d->>'chapter')::integer+6,d->>'slug',d->>'title',d->>'body',20,'review','[]'::jsonb,'chapter',10)
  ON CONFLICT(id) DO NOTHING;
  INSERT INTO public.lesson_constructs(lesson_id,construct_id,is_required,is_critical,min_questions)
  VALUES(sid,cid,true,false,1) ON CONFLICT(lesson_id,construct_id) DO NOTHING;
  FOR q IN SELECT value FROM jsonb_array_elements(d->'items') LOOP
    qid := (q->>'uuid')::uuid;
    IF EXISTS(SELECT 1 FROM public.questions WHERE id=qid AND source_reference NOT LIKE 'Scratch-LOGO-2026-v3:%') THEN
      RAISE EXCEPTION 'Question UUID collision: %',qid;
    END IF;
    INSERT INTO public.questions(id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,assets,is_generated,status,source_reference,source_lesson_id)
    VALUES(qid,subj,cid,d->>'group_code','Y1'::question_format,(q->>'cognitive')::cognitive_level,(q->>'difficulty')::integer,
      q->>'stem','[]'::jsonb,false,'review'::content_status,
      'Scratch-LOGO-2026-v3:'||(q->>'id')||'; source='||(q->>'source')||'; scope='||(q->>'scope'),sid)
    ON CONFLICT(id) DO NOTHING;
    FOR i IN 0..3 LOOP
      opt_id := (q->'option_ids'->>i)::uuid;
      INSERT INTO public.question_options(id,question_id,side,order_idx,content_md)
      VALUES(opt_id,qid,'a',i,q->'opts'->>i)
      ON CONFLICT(id) DO NOTHING;
    END LOOP;
    INSERT INTO public.question_keys(question_id,payload,explanation_md)
    VALUES(qid,jsonb_build_object('correct_option_id',(q->'option_ids'->>(q->>'correct')::integer)::uuid),
      (q->>'why')||E'\n\nManba: '||(q->>'source')) ON CONFLICT(question_id) DO NOTHING;
  END LOOP;
END $do$;


