F 27","scope":"TEXTBOOK_EXTENSION","format":"Y1","uuid":"9ea7d84c-6361-5852-8124-85d3f609c729","difficulty":4,"cognitive":"qollash","option_ids":["00466a76-083a-5668-8f79-22bee00db466","275d7998-d8a1-54a2-81ec-2ca8bc8eb073","0f34de53-a11e-5773-9614-f77e3ddee87f","0c91c0a6-ab4b-5453-8669-65de3bd48f0c"]},{"id":"SL3-02-005","ch":2,"level":"E","stem":"Tasvir ichini bitta rangga bo‘yashda qaysi uskuna qo‘l keladi?","opts":["Select","Fill","Eraser","Text"],"correct":1,"answer":"Fill","why":"Fill bo‘yoq bilan maydonni to‘ldirish vositasi.","source":"ICT6-2021 PDF 24–27","scope":"TEXTBOOK_EXTENSION","format":"Y1","uuid":"85c32b8e-72b8-52d9-bd15-4ae8c9129345","difficulty":5,"cognitive":"mulohaza","option_ids":["f30d0481-f491-597f-8977-32385e8279bf","93712b40-fc4f-54ab-b3a2-3e7b2bc10b18","84d53098-947d-553e-aea0-2ca70bcad1be","4e34d3da-ca39-5cde-a3f9-c166d241e7ff"]},{"id":"SL3-02-006","ch":2,"level":"A","stem":"Kostyum markazi noto‘g‘ri joylashgan bo‘lsa, burilishda nima kuzatiladi?","opts":["Faqat ovoz chiqaradi","Kompyuter o‘chadi","Sprayt tasviri kutilmagan nuqta atrofida aylanadi","Scratch faylni o‘chiradi"],"correct":2,"answer":"Sprayt tasviri kutilmagan nuqta atrofida aylanadi","why":"Burilish markazi kostyum markazi bilan bog‘liq.","source":"ICT6-2021 PDF 26; grafik tahlil","scope":"TEXTBOOK_EXTENSION","format":"Y1","uuid":"8adf3672-30b2-5822-8625-92c5571aa98b","difficulty":1,"cognitive":"bilish","option_ids":["d05a330a-1927-5469-861d-50cf8cc87e45","45bad3d5-0625-54f3-a9e1-22a863abed37","303cdd02-1a5c-50aa-ac7e-f15829b6ceec","fb22f1d1-e572-5583-9041-63b99cb83b20"]},{"id":"SL3-02-007","ch":2,"level":"B","stem":"`Line` uskunasi nima chizadi?","opts":["To‘g‘ri chiziq","Faqat aylana","Faqat matn","Faqat klon"],"correct":0,"answer":"To‘g‘ri chiziq","why":"Line chiziq chizish vositasi.","source":"ICT6-2021 PDF 25","scope":"TEXTBOOK_EXTENSION","format":"Y1","uuid":"ac617c57-b0ec-51d0-b637-67fa88b98864","difficulty":2,"cognitive":"bilish","option_ids":["40f71376-28d9-5d26-9272-2505260249e8","e602bb74-e409-5bb0-9f14-273e94353174","2288dbb3-ac5f-59a9-95e3-a82683956e2b","5057a6ab-0494-5805-9cf1-6748ec3a19b3"]},{"id":"SL3-02-008","ch":2,"level":"C","stem":"Bir kostyumdan boshqasiga o‘tish uchun qaysi blok mos?","opts":["clear graphic effects","next costume","play sound until done","delete this clone"],"correct":1,"answer":"next costume","why":"next costume ketma-ket kostyumga o‘tkazadi.","source":"ICT5-2020 PDF 95–105; ICT6-2021 PDF 18","scope":"TEXTBOOK_EXTENSION","format":"Y1","uuid":"e5acc96e-fd2e-570d-8176-b385c0218e6a","difficulty":3,"cognitive":"qollash","option_ids":["dcc7d16e-6e77-5a37-8751-eb9ad111e480","54adbe87-7754-52ed-b72d-2331c942b8c8","7b420edc-3e93-5543-baeb-8e5c1fc34f0a","6e2085dd-e862-5871-bd5b-43319fbddcba"]},{"id":"SL3-02-009","ch":2,"level":"D","stem":"Kostyumlar ro‘yxatini ko‘paytirish loyihadagi qaysi imkoniyatni kuchaytiradi?","opts":["Sprayt ko‘rinishlarini almashtirib animatsiya qilish","Faqat koordinata o‘qini yashirish","Papkalar yaratish","Internet ulanishini yaxshilash"],"correct":0,"answer":"Sprayt ko‘rinishlarini almashtirib animatsiya qilish","why":"Kostyum almashuvi harakat illuziyasini beradi.","source":"ICT5-2020 PDF 94–109; ICT6-2021 PDF 24–30","scope":"TEXTBOOK_EXTENSION","format":"Y1","uuid":"c9425345-3d79-53ea-8ae6-d6cae452d5ba","difficulty":4,"cognitive":"qollash","option_ids":["7190135f-630b-5fab-aded-7ca0b6af55c2","8823b4ed-fc50-505f-b1d7-f52104de432b","ffba1ba3-20a7-587d-b594-da25a2a7f02f","7bead291-dc5c-5402-b36a-aebf3c54f984"]},{"id":"SL3-02-010","ch":2,"level":"E","stem":"`Select` uskunasi vazifasi nima?","opts":["Tasodifiy son yaratish","Tasvir qismini yoki obyektni tanlash","Klonni o‘chirish","Siklni to‘xtatish"],"correct":1,"answer":"Tasvir qismini yoki obyektni tanlash","why":"Select tanlash vositasi.","source":"ICT6-2021 PDF 25–27","scope":"TEXTBOOK_EXTENSION","format":"Y1","uuid":"7b82f6cb-bb8c-51d2-b37d-78d9ebda4cd1","difficulty":5,"cognitive":"mulohaza","option_ids":["6027bad9-1e20-5029-b5f8-cc7ee872a19d","ab5dafc4-02b3-5fff-ae33-a7b545961481","c522dffd-86ec-5d0d-aa1d-770c456ff3ea","d7fd439c-1b04-579c-b942-5ce341ab6c00"]}]}$p$::jsonb;
  mid uuid; sid uuid := (d->>'lesson_id')::uuid; cid uuid := (d->>'construct_id')::uuid;
  subj uuid; q jsonb; qid uuid; opt_id uuid; i integer;
BEGIN
  SELECT id, subject_id INTO mid, subj FROM public.modules WHERE code='M07';
  IF mid IS NULL OR subj IS NULL THEN RAISE EXCEPTION 'M07 module not found'; END IF;
  IF d->>'kind'='extension' THEN
    INSERT INTO public.constructs(id,subject_id,group_code,code,slug,title_uz,description_uz)
    VALUES(cid,subj,d->>'group_code',d->>'construct_code',lower(replace(d->>'construct_code','.','-')),
      d->>'construct_title','2026 attestatsiya uchun qo‘shimcha darslik ko‘nikmasi, spetsifikatsiyada alohida kvota emas')
    ON CONFLICT(code) DO NOTHING;
  END IF;
  SELECT id INTO cid FROM public.constructs WHERE code=d->>'construct_code' AND subject_id=subj AND group_code=d->>'group_code';
  IF cid IS NULL THEN RAISE EXCEPTION 'Missing or incompatible construct: %', d->>'construct_code'; END IF;
  IF EXISTS(SELECT 1 FROM public.lessons WHERE id=sid AND (module_id<>mid OR slug<>d->>'slug')) THEN
    RAISE EXCEPTION 'Lesson id collision, chapter %', d->>'chapter';
  END IF;
  INSERT INTO public.lessons(id,module_id,order_idx,slug,title_uz,body_mdx,est_minutes,status,blocks,blocks_kind,topic_test_question_count)
  VALUES(sid,mid,(d->>'chapter')::integer+6,d->>'slug',d->>'title',d->>'body',20,'review','[]'::jsonb,'chapter',10)
  ON CONFLICT(id) DO NOTHING;
  INSERT INTO public.lesson_constructs(lesson_id,construct_id,is_required,is_critical,min_questions)
  VALUES(sid,cid,true,false,1) ON CONFLICT(lesson_id,construct_id) DO NOTHING;
  FOR q IN SELECT value FROM jsonb_array_elements(d->'items') LOOP
    qid := (q->>'uuid')::uuid;
    IF EXISTS(SELECT 1 FROM public.questions WHERE id=qid AND source_reference NOT LIKE 'Scratch-LOGO-2026-v3:%') THEN
      RAISE EXCEPTION 'Question UUID collision: %',qid;
    END IF;
    INSERT INTO public.questions(id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,assets,is_generated,status,source_reference,source_lesson_id)
    VALUES(qid,subj,cid,d->>'group_code','Y1'::question_format,(q->>'cognitive')::cognitive_level,(q->>'difficulty')::integer,
      q->>'stem','[]'::jsonb,false,'review'::content_status,
      'Scratch-LOGO-2026-v3:'||(q->>'id')||'; source='||(q->>'source')||'; scope='||(q->>'scope'),sid)
    ON CONFLICT(id) DO NOTHING;
    FOR i IN 0..3 LOOP
      opt_id := (q->'option_ids'->>i)::uuid;
      INSERT INTO public.question_options(id,question_id,side,order_idx,content_md)
      VALUES(opt_id,qid,'a',i,q->'opts'->>i)
      ON CONFLICT(id) DO NOTHING;
    END LOOP;
    INSERT INTO public.question_keys(question_id,payload,explanation_md)
    VALUES(qid,jsonb_build_object('correct_option_id',(q->'option_ids'->>(q->>'correct')::integer)::uuid),
      (q->>'why')||E'\n\nManba: '||(q->>'source')) ON CONFLICT(question_id) DO NOTHING;
  END LOOP;
END $do$;


