DO $do$
DECLARE
  d jsonb := $p${"chapter":5,"lesson_id":"4ca462ee-0503-5352-ab44-e5bb4ff495a8","slug":"scratch-v3-pen-geometriya","title":"Scratch 3.0: Pen va geometrik naqshlar","body":"# Scratch Pen — geometrik chizmalarni tahlil qilish\n\n**Maqsad.** Pen bilan chiziq chizish, sikl orqali muntazam ko‘pburchak yaratish, tashqi burilish burchagini topish.\n\n**Manbalar:** ICT 5-sinf (2020), PDF 103–107; Cambridge 6-sinf, PDF 125–143. **Spetsifikatsiya:** asosiy `S4.BLOCK.04`.\n\n## Pen amallari\n\n`pen down` qalamni tushiradi va keyingi harakat chiziq chizadi. `pen up` harakatni davom ettiradi, lekin iz qoldirmaydi. `erase all` avval chizilgan Pen izlarini o‘chiradi. Qalam o‘lchami chiziq qalinligiga ta’sir qiladi.\n\n## Muntazam shakllar\n\nMuntazam **n**-burchak uchun tashqi burilish burchagi:\n\n`360° / n`\n\n| Shakl | Tomonlar | Har safargi tashqi burilish |\n|---|---:|---:|\n| Teng tomonli uchburchak | 3 | 120° |\n| Kvadrat | 4 | 90° |\n| Muntazam oltiburchak | 6 | 60° |\n| Sakkizburchak | 8 | 45° |\n\n```text\npen down\nrepeat (4)\n  move (50) steps\n  turn right (90) degrees\nend\n```\n\nNatija — tomoni **50 qadamli kvadrat**. Jami Pen izi **200 qadam**. Qalam tushirilmasdan chizish boshlangan bo‘lsa, bunday iz hosil bo‘lmaydi.\n\n**Mavzu testi:** `SL3-05-001`–`SL3-05-010` (10 ta).","construct_id":"15614f33-3e9d-4ac6-825f-64617661c946","construct_code":"S4.BLOCK.04","group_code":"S4.BLOCK","construct_title":"Scratch 3.0: Pen va geometrik naqshlar","kind":"core","items":[{"id":"SL3-05-001","ch":5,"level":"A","stem":"Scratch Pen bilan chizishni boshlash uchun qaysi buyruq ishlatiladi?","opts":["pen up","clear","pen down","hide"],"correct":2,"answer":"pen down","why":"Pen down harakat izini chizdiradi.","source":"ICT5-2020 PDF 103–107; CAM6 PDF 125–143","scope":"SPEC","format":"Y1","uuid":"a3ca5744-de3f-5bab-873e-2e787c617c85","difficulty":1,"cognitive":"bilish","option_ids":["11e3b9fb-38b3-54b4-ab7b-5f8742dfd426","6a57bd49-80ec-5a3c-9b47-ff0fe4d7f26e","000ef5ad-d2c8-5905-a9bd-6137e59ea88d","dfcba62f-9153-5061-9def-33bd94c60b66"]},{"id":"SL3-05-002","ch":5,"level":"B","stem":"`repeat 4 [move 50; turn 90]` va pen down natijasi qanday?","opts":["Faqat nuqta","Muntazam beshburchak","Kvadrat konturi","Teng tomonli uchburchak"],"correct":2,"answer":"Kvadrat konturi","why":"To‘rtta teng tomon va 90° tashqi burilish kvadrat beradi.","source":"ICT5-2020 PDF 103–107","scope":"SPEC","format":"Y1","uuid":"9d7d0deb-f0f7-5896-b806-214cc8bba4f2","difficulty":2,"cognitive":"bilish","option_ids":["3d325faf-7a72-5cac-88a6-08d537a4ef43","324b5470-ca6d-5bd7-89e3-c660d0a30a25","ff89856f-cd63-5943-95c0-e6f2c041ba82","b3ee09c0-a750-5135-9536-3a865073b78f"]},{"id":"SL3-05-003","ch":5,"level":"C","stem":"Teng tomonli uchburchak chizishda har qadamdan keyingi tashqi burilish qancha?","opts":["90°","60°","120°","180°"],"correct":2,"answer":"120°","why":"360/3=120° tashqi burilish.","source":"CAM6 PDF 125–143","scope":"SPEC","format":"Y1","uuid":"acb235dd-59a5-567f-a0a5-306e723f03f0","difficulty":3,"cognitive":"qollash","option_ids":["e91bc63c-d8e7-5044-8031-704c961bca43","add59046-64ba-5ee1-bb66-06b3b0a82911","2a5dcc33-bd61-5731-bc2d-bbb5f1393c74","d00c7f59-e41d-5bd6-a8f9-3e0dd84cde09"]},{"id":"SL3-05-004","ch":5,"level":"D","stem":"6 tomonli muntazam shakl uchun tashqi burilish burchagi qancha?","opts":["120°","30°","90°","60°"],"correct":3,"answer":"60°","why":"360/6=60°.","source":"CAM6 PDF 125–143","scope":"SPEC","format":"Y1","uuid":"cbdeaeb3-81e9-55ce-a73c-8aaf31022b92","difficulty":4,"cognitive":"qollash","option_ids":["cfac901f-52e7-5a49-97f1-9b38b997d201","368c0fb0-6516-5ae5-a7ed-4d1b31cb8ea8","6e161dec-e5b9-5bcf-b437-dd784c4e333f","7bef5865-1570-5274-9672-7bd396b3c750"]},{"id":"SL3-05-005","ch":5,"level":"E","stem":"`pen up` so‘ng `move 30` bo‘lsa qaysi natija to‘g‘ri?","opts":["Sprayt klonlanadi","Sprayt siljiydi, yangi chiziq chizilmaydi","Barcha oldingi izlar o‘chadi","30 px chiziq chiziladi"],"correct":1,"answer":"Sprayt siljiydi, yangi chiziq chizilmaydi","why":"Pen up harakatda iz qoldirmaydi.","source":"ICT5-2020 PDF 103–107","scope":"SPEC","format":"Y1","uuid":"bb628d45-2e36-50de-99af-93786cf1eb1e","difficulty":5,"cognitive":"mulohaza","option_ids":["445e1bb6-92b1-51df-bbac-571cfb8283a1","009bf1bb-ea3b-5bff-9507-459f44c4e1f4","6af9dd8d-f95d-5b5f-ba88-86271919727a","cee81bdd-a4c1-5aa0-9f59-7f451bdee3f0"]},{"id":"SL3-05-006","ch":5,"level":"A","stem":"`erase all` Pen buyrug‘i nima qiladi?","opts":["Spraytni o‘chiradi","Tugmalarni almashtiradi","Barcha ro‘yxatlarni o‘chiradi","Sahna ustidagi qalam izlarini tozalaydi"],"correct":3,"answer":"Sahna ustidagi qalam izlarini tozalaydi","why":"Erase all Pen izlarini o‘chiradi.","source":"ICT5-2020 PDF 103–107","scope":"SPEC","format":"Y1","uuid":"e600244c-38c8-5d62-bc37-6abeeb6bf679","difficulty":1,"cognitive":"bilish","option_ids":["a2b7d1cf-deb2-5551-8cb6-6f5cb7a51b84","6cf79cb9-ac02-52f7-8a75-8373859de3b0","41e24691-50b4-5b8e-9234-e26e2b22ca59","909a6e0a-ee61-5cd3-bc60-4897c58ce4f6"]},{"id":"SL3-05-007","ch":5,"level":"B","stem":"Muntazam sakkizburchak tashqi burilish burchagi qancha?","opts":["80°","45°","135°","30°"],"correct":1,"answer":"45°","why":"360/8=45°.","source":"CAM6 PDF 125–143","scope":"SPEC","format":"Y1","uuid":"87ae4eb3-f272-52ca-810e-a1e7556e6370","difficulty":2,"cognitive":"bilish","option_ids":["5b95c452-1bea-59da-9688-789282a2181f","5cbaa9f4-3af3-572b-baf7-7f35fc4bd18d","0cdfb98c-c1b1-5e19-b5c4-63847f6dce47","71f740e2-1bb7-5a38-ad20-e18aef1aba4c"]},{"id":"SL3-05-008","ch":5,"level":"C","stem":"Kvadratning har tomoni 25 qadam bo‘lsa, bir marta aylanib chizilgan iz uzunligi qancha?","opts":["50 qadam","25 qadam","90 qadam","100 qadam"],"correct":3,"answer":"100 qadam","why":"4×25=100 qadam.","source":"CAM6 PDF 125–143","scope":"SPEC","format":"Y1","uuid":"611ef163-3e38-57c0-9eac-5c44ab0fdb10","difficulty":3,"cognitive":"qollash","option_ids":["39145c4c-cf39-5e3f-a306-20c21827b8b6","0156bd30-4ae4-5392-8a24-5ac3d7184ca0","773a2537-0a16-5950-a107-762a71131bde","95d3e1c3-f99d-529d-8d7b-970a7195db3a"]},{"id":"SL3-05-009","ch":5,"level":"D","stem":"Bir nuqtadan ikkita kvadrat chizilib, ular orasida 45° burilsa, qanday kompozitsiya hosil bo‘ladi?","opts":["Faqat bitta chiziq","Ikkita alohida sahna","Faqat tasodifiy nuqtalar","Bir-biriga nisbatan burilgan ikki kvadrat"],"correct":3,"answer":"Bir-biriga nisbatan burilgan ikki kvadrat","why":"Har kvadrat boshlang‘ich nuqtaga qaytadi; keyingi yo‘nalish buriladi.","source":"CAM6 PDF 125–143; sintez","scope":"SPEC","format":"Y1","uuid":"686edd8f-1ffa-5fc1-ae3d-223f86861797","difficulty":4,"cognitive":"qollash","option_ids":["a956a17b-5439-5c76-ae42-f4ecf82e32d8","f55493ad-e01e-5f09-9417-2f24c28905e3","41b742b7-ddab-5b90-8658-f0a1a33f90f8","815f6f5f-cf47-5690-8b7b-0f4482f67fb0"]},{"id":"SL3-05-010","ch":5,"level":"E","stem":"Pen izining qalinligi 1 dan 5 ga o‘zgartirilsa, geometrik shaklning qaysi xususiyati o‘zgaradi?","opts":["Chiziq qalinligi","Sikl iteratsiyasi","Sprayt koordinatasi","Tomonlar soni"],"correct":0,"answer":"Chiziq qalinligi","why":"Pen size kontur qalinligini o‘zgartiradi.","source":"ICT5-2020 PDF 103–107","scope":"SPEC","format":"Y1","uuid":"2ea458f6-23b6-51a9-a7b3-80e3fdf7fa02","difficulty":5,"cognitive":"mulohaza","option_ids":["fe35a550-d5c0-5dc7-923a-be3f69d5ce83","392920f4-93ee-5219-b1f6-109a72992df6","4e54b25a-dc36-5e29-bf62-0badceacbcb3","c7cc9f9c-853b-52c9-93bd-7070e6448206"]}]}$p$::jsonb;
  mid uuid; sid uuid := (d->>'lesson_id')::uuid; cid uuid := (d->>'construct_id')::uuid;
  subj uuid; q jsonb; qid uuid; opt_id uuid; i integer;
BEGIN
  SELECT id, subject_id INTO mid, subj FROM public.modules WHERE code='M07';
  IF mid IS NULL OR subj IS NULL THEN RAISE EXCEPTION 'M07 module not found'; END IF;
  IF d->>'kind'='extension' THEN
    INSERT INTO public.constructs(id,subject_id,group_code,code,slug,title_uz,description_uz)
    VALUES(cid,subj,d->>'group_code',d->>'construct_code',lower(replace(d->>'construct_code','.','-')),
      d->>'construct_title','2026 attestatsiya uchun qo‘shimcha darslik ko‘nikmasi, spetsifikatsiyada alohida kvota emas')
    ON CONFLICT(code) DO NOTHING;
  END IF;
  SELECT id INTO cid FROM public.constructs WHERE code=d->>'construct_code' AND subject_id=subj AND group_code=d->>'group_code';
  IF cid IS NULL THEN RAISE EXCEPTION 'Missing or incompatible construct: %', d->>'construct_code'; END IF;
  IF EXISTS(SELECT 1 FROM public.lessons WHERE id=sid AND (module_id<>mid OR slug<>d->>'slug')) THEN
    RAISE EXCEPTION 'Lesson id collision, chapter %', d->>'chapter';
  END IF;
  INSERT INTO public.lessons(id,module_id,order_idx,slug,title_uz,body_mdx,est_minutes,status,blocks,blocks_kind,topic_test_question_count)
  VALUES(sid,mid,(d->>'chapter')::integer+6,d->>'slug',d->>'title',d->>'body',20,'review','[]'::jsonb,'chapter',10)
  ON CONFLICT(id) DO NOTHING;
  INSERT INTO public.lesson_constructs(lesson_id,construct_id,is_required,is_critical,min_questions)
  VALUES(sid,cid,true,false,1) ON CONFLICT(lesson_id,construct_id) DO NOTHING;
  FOR q IN SELECT value FROM jsonb_array_elements(d->'items') LOOP
    qid := (q->>'uuid')::uuid;
    IF EXISTS(SELECT 1 FROM public.questions WHERE id=qid AND source_reference NOT LIKE 'Scratch-LOGO-2026-v3:%') THEN
      RAISE EXCEPTION 'Question UUID collision: %',qid;
    END IF;
    INSERT INTO public.questions(id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,assets,is_generated,status,source_reference,source_lesson_id)
    VALUES(qid,subj,cid,d->>'group_code','Y1'::question_format,(q->>'cognitive')::cognitive_level,(q->>'difficulty')::integer,
      q->>'stem','[]'::jsonb,false,'review'::content_status,
      'Scratch-LOGO-2026-v3:'||(q->>'id')||'; source='||(q->>'source')||'; scope='||(q->>'scope'),sid)
    ON CONFLICT(id) DO NOTHING;
    FOR i IN 0..3 LOOP
      opt_id := (q->'option_ids'->>i)::uuid;
      INSERT INTO public.question_options(id,question_id,side,order_idx,content_md)
      VALUES(opt_id,qid,'a',i,q->'opts'->>i)
      ON CONFLICT(id) DO NOTHING;
    END LOOP;
    INSERT INTO public.question_keys(question_id,payload,explanation_md)
    VALUES(qid,jsonb_build_object('correct_option_id',(q->'option_ids'->>(q->>'correct')::integer)::uuid),
      (q->>'why')||E'\n\nManba: '||(q->>'source')) ON CONFLICT(question_id) DO NOTHING;
  END LOOP;
END $do$;


